def rewrite_ref(value: str) -> str:
    if value == POLICY_V1_DOC:
        return POLICY_V2_DOC
    if value.startswith(KEEP):
        return value
    for old, new in sorted(REWRITE.items(), key=lambda kv: -len(kv[0])):
        if value == old or value.startswith(old + "#"):
            return new + value[len(old) :]
    return value


def walk(node):
    if isinstance(node, dict):
        out = {}
        for k, v in node.items():
            if k in ("$id", "$ref") and isinstance(v, str):
                out[k] = rewrite_ref(v)
            else:
                out[k] = walk(v)
        return out
    if isinstance(node, list):
        return [walk(x) for x in node]
    return node


